	rows, err := q.db.Query(ctx, listRadioConversations, arg.FreshAfter, arg.Now, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRadioConversationsRow{}
	for rows.Next() {
		var i ListRadioConversationsRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Status,
			&i.Name,
			&i.CooperativeID,
			&i.Role,
			&i.MemberStatus,
			&i.Listening,
			&i.MutedByPeer,
			&i.BlockedByPeer,
			&i.Title,
			&i.HasPeer,
			&i.PeerID,
			&i.PeerStatus,
			&i.PeerOnline,
			&i.OnlineCount,
			&i.UnreadCount,
			&i.LastMessageAt,
			&i.PeerMuted,
			&i.PeerBlocked,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
